### 1. Enable flakes

Edit `/etc/nix/nix.conf` (create if missing):

```
sudo mkdir -p /etc/nix
echo "experimental-features = nix-command flakes" | sudo tee -a /etc/nix/nix.conf
```

---

### 2. Prepare your flake directory

Choose a directory for your flake config, e.g., `/etc/nixos/flake`:

```
sudo mkdir -p /etc/nixos/flake
cd /etc/nixos/flake
```

---

### 3. Create `flake.nix`

```nix
{
  description = "NixOS config with flakes and Home Manager";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    home-manager.url = "github:nix-community/home-manager";
    home-manager.inputs.nixpkgs.follows = "nixpkgs";
    flake-utils.url = "github:numtide/flake-utils";
  };

  outputs = { self, nixpkgs, home-manager, flake-utils, ... }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs {
          inherit system;
          config.allowUnfree = true;
        };
        username = "alice"; # CHANGE THIS
        hostname = "nixos"; # CHANGE THIS
      in {
        nixosConfigurations.${hostname} = pkgs.lib.nixosSystem {
          inherit system;
          modules = [
            ./configuration.nix
            home-manager.nixosModules.home-manager
            {
              home-manager.useGlobalPkgs = true;
              home-manager.useUserPackages = true;
              home-manager.users.${username} = import ./home.nix;
            }
          ];
        };
      }
    );
}
```

---

### 4. Create `configuration.nix`

```nix
{ config, pkgs, ... }:

{
  networking.hostName = "nixos"; # CHANGE THIS
  time.timeZone = "UTC";
  i18n.defaultLocale = "en_US.UTF-8";

  users.users.alice = { # CHANGE THIS
    isNormalUser = true;
    extraGroups = [ "wheel" "networkmanager" ];
    shell = pkgs.zsh;
  };

  services.xserver.enable = true;
  services.xserver.displayManager.gdm.enable = true;
  services.xserver.desktopManager.gnome.enable = true;
  services.xserver.displayManager.gdm.wayland = true;
  services.xserver.layout = "us";
  services.xserver.xkbOptions = "eurosign:e";
  services.xserver.videoDrivers = [ "modesetting" ];
  services.gnome.core-utilities.enable = true;

  services.networkmanager.enable = true;

  environment.systemPackages = with pkgs; [
    curl wget git htop tmux unzip zip tree gcc make
    neovim
    vscode
    brave
    bitwarden
    # zed may not be in nixpkgs; see below
  ];

  nix.settings.experimental-features = [ "nix-command" "flakes" ];

  system.stateVersion = "23.11"; # CHANGE to your NixOS version
}
```

---

### 5. Create `home.nix`

```nix
{ config, pkgs, ... }:

{
  home.username = "alice"; # CHANGE THIS
  home.homeDirectory = "/home/alice"; # CHANGE THIS

  programs.neovim.enable = true;
  programs.zsh.enable = true;
  programs.git.enable = true;

  home.packages = with pkgs; [
    # If zed is not in nixpkgs, fetch it manually:
    (pkgs.stdenv.mkDerivation {
      pname = "zed";
      version = "0.121.0"; # CHANGE to latest
      src = pkgs.fetchurl {
        url = "https://github.com/zed-industries/zed/releases/download/v0.121.0/zed-x86_64-unknown-linux-gnu.tar.gz";
        sha256 = "sha256-xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx"; # get with nix-prefetch-url
      };
      installPhase = ''
        mkdir -p $out/bin
        tar -xzf $src -C $out/bin --strip-components=1
      '';
    })
  ];
}
```

---

### 6. Build and switch

From `/etc/nixos/flake`:

```
sudo nixos-rebuild switch --flake .#nixos
```

---

### 7. Log in and enjoy

- Log in as your user.
- GNOME on Wayland should be running.
- All requested apps and tools should be available.

