```c
#include <stdio.h>

// Returns the largest index i such that arr[i] < target, or -1 if none exists
int findIndexLessThan(int arr[], int n, int target) {
    int left = 0, right = n - 1;
    int result = -1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (arr[mid] < target) {
            result = mid;
            left = mid + 1;
        } else {
            right = mid - 1;
        }
    }
    return result;
}

int main() {
    int arr[] = {2, 4, 6, 8, 10};
    int n = sizeof(arr) / sizeof(arr[0]);
    int target = 7;
    int idx = findIndexLessThan(arr, n, target);
    if (idx != -1)
        printf("Index: %d, Value: %d\n", idx, arr[idx]);
    else
        printf("No element less than %d found.\n", target);
    return 0;
}
```

**Explanation:**
