        } else if (child.nodeType === Node.ELEMENT_NODE) {
            // Skip code/pre blocks
            if (child.tagName.toLowerCase() === 'code' || child.tagName.toLowerCase() === 'pre') continue;
            highlightQuotesInElement(child);
        }
    }
}
```

