    var p1: Int = 0
    var p2: Int = 0
}

struct SetScore {
    var gamesP1: Int = 0
    var gamesP2: Int = 0
}

class Match: ObservableObject {
    @Published var sets: [SetScore] = [SetScore(), SetScore(), SetScore()]
    @Published var currentSet: Int = 0
    @Published var currentGame = GameScore()
    @Published var pointHistory: [PointRecord] = []

    func addPoint(player: Int, detail: PointDetail?) {
        // Update game score
        if player == 1 {
            currentGame.p1 += 1
        } else {
            currentGame.p2 += 1
        }
        // Log point detail if provided
        if let d = detail {
            pointHistory.append(PointRecord(player: "Player \(player)", detail: d, timestamp: Date()))
        }
        // Check for game win (simplified, not full tennis logic)
        if currentGame.p1 >= 4 && currentGame.p1 - currentGame.p2 >= 2 {
            sets[currentSet].gamesP1 += 1
            currentGame = GameScore()
            checkSetWin()
        } else if currentGame.p2 >= 4 && currentGame.p2 - currentGame.p1 >= 2 {
            sets[currentSet].gamesP2 += 1
            currentGame = GameScore()
            checkSetWin()
        }
    }

    func checkSetWin() {
        let set = sets[currentSet]
        if (set.gamesP1 >= 6 || set.gamesP2 >= 6) && abs(set.gamesP1 - set.gamesP2) >= 2 {
            if currentSet < 2 {
                currentSet += 1
            }
        }
    }

