import SwiftUI

struct EqualizerView: View {
    var audioPower: Float
    let barCount = 5

    private func normalizedPower(_ power: Float) -> CGFloat {
        let minDb: Float = -60
        let clamped = max(power, minDb)
        return CGFloat((clamped - minDb) / -minDb)
    }

    var body: some View {
        HStack(spacing: 6) {
            ForEach(0..<barCount, id: \.self) { _ in
                let height = normalizedPower(audioPower) * CGFloat.random(in: 0.5...1.0) * 100
                RoundedRectangle(cornerRadius: 3)
