---

**My Answer:**

This is a classic minimum spanning tree (MST) problem with a twist: some edges (roads) already exist, and the cost to build a new road between two houses is the sum of their prices. The goal is to ensure the city is fully connected at minimal cost.

**Approach:**

1. **Model the city as a graph:** Houses are nodes, roads are edges.
2. **Find connected components:** Use Union-Find (DSU) to process the existing roads and identify connected components.
3. **For each component, find the house with the lowest price.**
4. **Connect all components:** To minimize cost, connect all components to the component containing the globally cheapest house. For each other component, connect its cheapest house to the globally cheapest house.
5. **Output:** The number of new roads and the list of roads to build.

**C++ Implementation:**

```cpp
#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent;
    DSU(int n) : parent(n) {
        iota(parent.begin(), parent.end(), 0);
    }
    int find(int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        parent[find(x)] = find(y);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;
    vector<long long> a(n);
    for (int i = 0; i < n; ++i) cin >> a[i];

    DSU dsu(n);
    for (int i = 0; i < m; ++i) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        dsu.unite(u, v);
    }

    // Find the cheapest house in each component
    vector<int> min_in_comp(n, -1);
    for (int i = 0; i < n; ++i) {
        int p = dsu.find(i);
        if (min_in_comp[p] == -1 || a[i] < a[min_in_comp[p]])
            min_in_comp[p] = i;
    }

    // Find the globally cheapest house
    int global_min = -1;
    for (int i = 0; i < n; ++i) {
        if (min_in_comp[i] != -1) {
            if (global_min == -1 || a[min_in_comp[i]] < a[global_min])
                global_min = min_in_comp[i];
        }
    }

    // Connect all other components to the global_min
    vector<pair<int, int>> roads;
    int root = dsu.find(global_min);
    for (int i = 0; i < n; ++i) {
        if (min_in_comp[i] != -1 && dsu.find(min_in_comp[i]) != root) {
            roads.emplace_back(global_min + 1, min_in_comp[i] + 1);
            dsu.unite(global_min, min_in_comp[i]);
        }
