To create character movement that adapts to arbitrary surfaces (cube, sphere, custom mesh) and rotates the character to align with the surface normal in Unity 2023, you need to:

1. Detect the surface normal beneath the character (using raycasting).
2. Align the character's up direction with the surface normal.
3. Move the character along the tangent of the surface (project movement input onto the surface).
4. Apply gravity or a "stick to surface" force along the normal.

Here's a basic C# script using a Rigidbody approach (can be adapted for CharacterController):

```csharp
using UnityEngine;

public class SurfaceWalker : MonoBehaviour
{
    public float moveSpeed = 5f;
    public float rotationSpeed = 10f;
    public float gravity = 9.81f;
    public float raycastDistance = 2f;

    private Rigidbody rb;

    void Start()
    {
        rb = GetComponent<Rigidbody>();
        rb.freezeRotation = true;
    }

    void FixedUpdate()
    {
        // 1. Raycast down to find the surface and its normal
        if (Physics.Raycast(transform.position, -transform.up, out RaycastHit hit, raycastDistance))
        {
            Vector3 normal = hit.normal;

            // 2. Align character's up with surface normal
            Quaternion targetRot = Quaternion.FromToRotation(transform.up, normal) * transform.rotation;
            transform.rotation = Quaternion.Slerp(transform.rotation, targetRot, rotationSpeed * Time.deltaTime);

            // 3. Get input and project movement onto surface
            float h = Input.GetAxis("Horizontal");
            float v = Input.GetAxis("Vertical");
            Vector3 input = new Vector3(h, 0, v);

            if (input.sqrMagnitude > 0.01f)
            {
                input = transform.TransformDirection(input);
                Vector3 moveDir = Vector3.ProjectOnPlane(input, normal).normalized;
                Vector3 velocity = moveDir * moveSpeed;
                Vector3 gravityForce = -normal * gravity;
                rb.velocity = velocity + gravityForce;
            }
            else
            {
                rb.velocity = -normal * gravity;
            }
        }
        else
        {
            rb.AddForce(Physics.gravity, ForceMode.Acceleration);
        }
    }
}
```

**Key Points:**
- Raycast from the character's position in the direction opposite to its up vector.
- Use the hit normal to align the character's up direction.
- Project movement input onto the surface tangent.
- Apply gravity along the surface normal to keep the character "stuck" to the surface.

