// Create a point mesh with UVs matching the texture
void CreatePointMesh(Texture2D tex)
{
    int w = tex.width, h = tex.height;
    Vector3[] verts = new Vector3[w * h];
    Vector2[] uvs = new Vector2[w * h];
    int[] indices = new int[w * h];
    for (int y = 0; y < h; ++y)
    for (int x = 0; x < w; ++x)
    {
        int i = y * w + x;
        verts[i] = new Vector3(x, y, 0);
        uvs[i] = new Vector2((float)x / w, (float)y / h);
        indices[i] = i;
    }
    Mesh mesh = new Mesh();
    mesh.vertices = verts;
    mesh.uv = uvs;
    mesh.SetIndices(indices, MeshTopology.Points, 0);
    GetComponent<MeshFilter>().mesh = mesh;
}
