**C++ Code:**

```cpp
#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

// Function to add two big integers represented as strings
string addBig(const string &a, const string &b) {
    string res = "";
    int carry = 0, i = a.size() - 1, j = b.size() - 1;
    while (i >= 0 || j >= 0 || carry) {
        int x = (i >= 0 ? a[i--] - '0' : 0);
        int y = (j >= 0 ? b[j--] - '0' : 0);
        int sum = x + y + carry;
        carry = sum / 10;
        res.push_back('0' + sum % 10);
    }
    reverse(res.begin(), res.end());
    return res;
}

// Function to compare two big integers as strings
// Returns 1 if a > b, -1 if a < b, 0 if equal
int compareBig(const string &a, const string &b) {
    if (a.size() > b.size()) return 1;
    if (a.size() < b.size()) return -1;
    for (int i = 0; i < a.size(); ++i) {
        if (a[i] > b[i]) return 1;
        if (a[i] < b[i]) return -1;
    }
    return 0;
}

int main() {
    int n;
    cin >> n;
    string sum1 = "0", sum2 = "0", s;
    for (int i = 0; i < n; ++i) {
        cin >> s;
        sum1 = addBig(sum1, s);
    }
    for (int i = 0; i < n; ++i) {
        cin >> s;
        sum2 = addBig(sum2, s);
    }
    if (compareBig(sum1, sum2) > 0)
        cout << "one";
    else
        cout << "two";
    return 0;
}
```

