#include <iostream>
#include <cstring>
using namespace std;

int main() {
    char a[110]; // 100 digits + possible carry + '\0'
    char b_char;
    cin >> a;
    cin >> b_char;
    int b = b_char - '0';

    int len = strlen(a);
    int carry = b;
    // We'll store the result in reverse order
    int result[110];
    int pos = 0;

    // Add from the least significant digit
    for (int i = len - 1; i >= 0; i--) {
        int sum = (a[i] - '0') + carry;
        result[pos++] = sum % 10;
        carry = sum / 10;
    }
    // If there's still a carry
    while (carry > 0) {
        result[pos++] = carry % 10;
        carry /= 10;
    }
    // Output in correct order
    for (int i = pos - 1; i >= 0; i--) {
        cout << result[i];
    }
    cout << endl;
    return 0;
}
