#include <algorithm>
struct Point { double x, y; };
Point operator-(const Point& a, const Point& b) { return {a.x-b.x, a.y-b.y}; }
Point operator+(const Point& a, const Point& b) { return {a.x+b.x, a.y+b.y}; }
Point operator*(const Point& a, double s) { return {a.x*s, a.y*s}; }
double dot(const Point& a, const Point& b) { return a.x*b.x + a.y*b.y; }
double norm(const Point& a) { return std::sqrt(a.x*a.x + a.y*a.y); }
Point normalize(const Point& a) { double n=norm(a); return {a.x/n, a.y/n}; }

bool pointInCapsule(const Point& p, const Point& s, const Point& e, double halfW) {
    Point u = e-s, v = p-s;
    double t = dot(u, u) > 0 ? dot(v, u)/dot(u, u) : 0;
    t = std::max(0.0, std::min(1.0, t));
    Point proj = s + u*t;
    return norm(p - proj) <= halfW;
}

bool isCovered(const Point& A1, const Point& A2, double wA,
               const Point& B1, const Point& B2, double wB) {
    Point dirB = normalize(B2-B1);
    Point nB = {-dirB.y, dirB.x};
    double hwB = wB/2, hwA = wA/2;
    Point P1 = B1 + nB*hwB, P2 = B1 - nB*hwB;
    Point P3 = B2 + nB*hwB, P4 = B2 - nB*hwB;
