        r = a - q * b;
        X = X2 - q * X1;
        Y = Y2 - q * Y1;
        a = b;
        b = r;
        X2 = X1;
        X1 = X;
        Y2 = Y1;
        Y1 = Y;
    }
    *d = a;
    *x = X2;
    *y = Y2;
}

